actions.script:
File directory = new File(ec.factory.runtimePath, 'ownerData')
if (!directory.isDirectory() && !directory.mkdirs()) {
    throw new IllegalStateException('Unable to prepare SQLite review storage')
}
File temp = File.createTempFile('nasqo-sqlite-import-', '.back', directory)
try {
    // Hard cap incoming upload before it can exhaust the server disk.
    final long maxSize = 256L * 1024L * 1024L
    if (file.size <= 0L || file.size > maxSize) {
        throw new IllegalArgumentException('SQLite backup must be 1 byte to 256 MB')
    }
    file.inputStream.withCloseable { InputStream input ->
        new java.io.FileOutputStream(temp).withCloseable { OutputStream output ->
            byte[] bytes = new byte[64 * 1024]
            long size = 0L
            int amount
            while ((amount = input.read(bytes)) != -1) {
                size += amount
                if (size > maxSize) throw new IllegalArgumentException('SQLite upload too large')
                output.write(bytes, 0, amount)
            }
        }
    }
    def util = ec.resource.script('component://growerp/service/NasqoSqliteImportUtil.groovy', null)
    preview = util.preview(temp)
    // Explicit company-scoped operator opt-in; no other tenant is
    // allowed to persist a source by calling this preview.
    String stagingCompany = System.getenv('NASQO_ACCOUNTING_STAGE_COMPANY')
    if (stagingCompany &amp;&amp; companyPartyId?.toString() == stagingCompany) {
        try {
            File privateRoot = new File('/var/lib/nasqo-accounting-imports')
            preview.accountingStage = util.stageForAccounting(
                temp, privateRoot, companyPartyId.toString())
            preview.warnings &lt;&lt;
                'تم حفظ ملف المصدر في مساحة مراجعة محاسبية خاصة على خادم نسقو. لم تُرحّل أي قيود أو أرصدة.'
        } catch (Exception reviewError) {
            preview.accountingStage = [
                status: 'NOT_STAGED', postedEntries: 0,
                sourceRowsWrittenToAccounting: 0
            ]
            preview.warnings &lt;&lt;
                'تعذّر تجهيز الملف للمراجعة المحاسبية؛ لا توجد قيود أو أرصدة مستوردة.'
        }
    }
} finally {
    temp.delete()
}
